urlset:
{% for sitemap_entry in entries %}
    {% if not sitemap_entry.extra.unlisted %}

        {{ sitemap_entry.permalink | safe }}
        {% if sitemap_entry.updated %}
        {{ sitemap_entry.updated | date(format="%Y-%m-%d") }}
        {% elif sitemap_entry.date %}
        {{ sitemap_entry.date | date(format="%Y-%m-%d") }}
        {% endif %}

    {% endif %}
{% endfor %}
